import {
  arrow as arrowFn,
  autoUpdate,
  computePosition,
  flip,
  offset as offsetFn,
  shift,
} from '@floating-ui/dom'
import { mix, splitUnit, toRadians } from '@splendidlabz/utils'
import { getCSSVar, setCSSVar, toPx } from '@splendidlabz/utils/dom'

// TODO: Add inline for tooltips
export const FLOATING_OPTS = {
  placement: 'top',
  strategy: 'absolute',
  offset: '0',
  arrow: false,
  arrowHeight: 0,
  arrowRadius: '5px',
  boxStyle: 'standard', // standard, fancy
  useReferenceBoundaries: false,
}

export const FLOATING_OPTS_KEYS = Object.keys(FLOATING_OPTS)

export function initFloating(options) {
  options = mix(FLOATING_OPTS, options)
  const {
    referenceNode,
    floatingNode,
    boxStyle,
    arrow,
    strategy,
    placement,
    arrowRadius,
    offset: offsetValue,
  } = options
  let _cleanup = null

  // Determine box style and apply styles as necessary.
  applyBoxStyles(options)

  // Get necessary values
  const borderWidth = toPx(
    getCSSVar(floatingNode, 'border-width'),
    floatingNode,
  )
  const borderRadius = toPx(
    getCSSVar(floatingNode, 'border-radius'),
    floatingNode,
  )

  // Create arrow node — used for both styles
  const arrowNode = document.createElement('div')
  const arrowClass = 'popover-content-arrow'
  const arrowHeight = resolveArrowHeight(options)
  const arrowWidth = getArrowWidth({ ...options, arrowHeight })

  const arrowProps = {
    arrow,
    arrowNode,
    arrowWidth,
    arrowHeight,
    arrowRadius,
  }

  applyArrowStyles({ boxStyle, ...arrowProps })
  arrowNode.classList.add(arrowClass)
  if (arrow) floatingNode.appendChild(arrowNode)

  // Calculate offset
  const offset = calculateOffset({
    floatingNode,
    boxStyle,
    arrow,
    borderWidth,
    offsetValue,
    arrowHeight,
  })

  // Create floating options
  const floatingOpts = {
    strategy,
    placement,
    middleware: [
      offsetFn(offset),
      flip({ fallbackAxisSideDirection: 'start' }),
      shift(),
      arrow && arrowFn({ element: arrowNode }),
    ],
  }

  return {
    // Update floating position.
    // Run when mounting.
    update() {
      _cleanup = autoUpdate(referenceNode, floatingNode, _ => {
        computePosition(referenceNode, floatingNode, floatingOpts).then(
          middlewareState => {
            const { x, y } = middlewareState

            // Position Popover
            Object.assign(floatingNode.style, {
              left: `${x}px`,
              top: `${y}px`,
            })

            if (!arrow) return

            // Position arrow
            positionArrow({
              ...options,
              ...arrowProps,
              borderWidth,
              borderRadius,
              middlewareState,
            })
          },
        )
      })
    },

    // Cleanup autoupdate.
    // Run when dismounting.
    cleanup() {
      if (_cleanup) _cleanup()
    },
  }
}

function applyBoxStyles({
  referenceNode,
  floatingNode,
  strategy,
  boxStyle,
  placement,
  arrow,
  useReferenceBoundaries,
}) {
  floatingNode.style.position = strategy
  floatingNode.style.overflow = 'visible' // Users can specify max-height on the popover content to enable scrolling.

  if (useReferenceBoundaries) {
    const { width, height } = referenceNode.getBoundingClientRect()

    if (['top', 'bottom'].includes(placement)) {
      floatingNode.style.width = `${width}px`
    }

    if (['left', 'right'].includes(placement)) {
      floatingNode.style.height = `${height}px`
    }
  }

  if (boxStyle === 'fancy') {
    if (!arrow) floatingNode.classList.add('fancybox')
    else {
      const side = getArrowSide(placement)
      floatingNode.classList.add('fancybox-arrow', `arrow-${side}`)
    }
  }
}

function resolveArrowHeight({ floatingNode, arrow, arrowHeight, boxStyle }) {
  if (!arrow) return 0
  if (boxStyle === 'standard') return toPx(arrowHeight, floatingNode)

  // Fancy box style
  if (arrowHeight) {
    const h = toPx(arrowHeight, floatingNode)
    setCSSVar(floatingNode, '--h', `${h}px`)
    return h
  } else {
    const h = getCSSVar(floatingNode, '--h')
    return toPx(h, floatingNode)
  }
}

function getArrowWidth({ boxStyle, floatingNode, arrowHeight }) {
  // Standard box is a square, so it must use the same value for both width and height
  if (boxStyle === 'standard') return arrowHeight

  // Fancy box can have different width and height values depending on the angle used. Downside is the arrow will never be rounded.

  let [angle, unit] = splitUnit(getCSSVar(floatingNode, '--a'))
  if (unit === 'deg') angle = toRadians(angle)
  return Math.tan(angle / 2) * arrowHeight * 2
}

function getArrowSide(placement) {
  const side = {
    top: 'bottom',
    right: 'left',
    bottom: 'top',
    left: 'right',
  }[placement.split('-')[0]]
  return side
}

function applyArrowStyles({
  arrowNode,
  arrowWidth,
  arrowHeight,
  arrowRadius,
  boxStyle,
}) {
  // Need to check which borders and radius to remove
  const styles = {
    width: `${arrowWidth}px`,
    height: `${arrowHeight}px`,
    position: 'absolute',
    borderRadius: '0',
    borderTopRightRadius: arrowRadius,
    borderWidth: 'inherit',
    borderColor: 'inherit',
    borderLeftWidth: '0',
    borderBottomWidth: '0',
    background: 'inherit',
  }

  if (boxStyle === 'fancy') {
    Object.assign(styles, { opacity: '0' })
  }

  Object.assign(arrowNode.style, styles)
}

function calculateOffset({
  floatingNode,
  boxStyle,
  offsetValue,
  borderWidth,
  arrow,
  arrowHeight,
}) {
  let offset = toPx(offsetValue, floatingNode)
  if (!arrow) return offset

  if (boxStyle === 'standard') {
    const arrowHypotenuse = Math.sqrt(arrowHeight ** 2 + borderWidth ** 2)
    offset += Math.floor(arrowHypotenuse / 2)
  }
  if (boxStyle === 'fancy') offset += arrowHeight
  return offset
}

function positionArrow({
  floatingNode,
  middlewareState,
  arrowNode,
  arrowWidth,
  arrowHeight,
  borderWidth,
  borderRadius,
  boxStyle,
}) {
  const { placement } = middlewareState
  const { x, y } = middlewareState.middlewareData.arrow
  const { width, height } = floatingNode.getBoundingClientRect()

  // Do nothing if popover is not opened yet
  if (!(width || height)) return
  // Do nothing if no arrow data
  if (!(x || y)) return

  const side = getArrowSide(placement)

  if (boxStyle === 'standard') {
    // Rotate arrow box
    let rotate = 45
    // prettier-ignore
    switch (side) {
      case 'top': rotate = -45; break; 
      case 'right': rotate = 45; break;
      case 'bottom': rotate = 135; break;
      case 'left': rotate = 225; break;
    }

    const adjusted = { x, y }
    const safetySpace = 3

    if (x || x === 0) {
      const startEdge = borderRadius + safetySpace
      const endEdge = width - borderRadius - arrowWidth - safetySpace

      if (x <= startEdge) adjusted.x = startEdge
      if (x >= endEdge) adjusted.x = endEdge
    }

    if (y || y === 0) {
      const startEdge = borderRadius + safetySpace
      const endEdge = height - borderRadius - arrowWidth - safetySpace

      if (y <= startEdge) adjusted.y = startEdge
      if (y >= endEdge) adjusted.y = endEdge
    }

    const arrowCrossOffset = Math.ceil((arrowHeight + borderWidth) / 2)

    // prettier-ignore
    Object.assign(arrowNode.style, {
      left: x ? `${adjusted.x}px` : '',
      top: y ? `${adjusted.y}px` : '',
      [side]: `-${arrowCrossOffset}px`,
      transform: `rotate(${rotate}deg)`,
    })
  }

  if (boxStyle === 'fancy') {
    if (x) arrowNode.style.left = `${x}px`
    if (y) arrowNode.style.top = `${y}px`

    let arrowCenter, arrowPosition
    if (x) {
      arrowCenter = x + arrowWidth / 2
      arrowPosition = ((arrowCenter + borderWidth) / width) * 100
    }
    if (y) {
      arrowCenter = y + arrowWidth / 2
      arrowPosition = ((arrowCenter + borderWidth) / height) * 100
    }

    floatingNode.classList.remove(
      'arrow-top',
      'arrow-right',
      'arrow-bottom',
      'arrow-left',
    )
    floatingNode.classList.add(`arrow-${side}`)
    setCSSVar(floatingNode, '--arrow-position', `${arrowPosition}%`)
  }
}
